---@class CommRoleBonusLayoutGroupNode
local CommRoleBonusLayoutGroupNode = Class('CommRoleBonusLayoutGroupNode')
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local CommRoleBonusLayoutGroupCell = "Game.Behaviours.CommRoleBonusLayoutGroupCell"
local Utils        = CS.Engine.Tools.Utils
local UIEventProxy = CS.Engine.UI.UIEventProxy
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local RectTransformUtility = CS.UnityEngine.RectTransformUtility
local UIModule     = CS.Engine.UI.UIModule
---@type CardComponent
local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)

function CommRoleBonusLayoutGroupNode:__init()
	self.isInitDropDown  = false
	self.alignCellList = {}
	self.selectIndex = 1
end

function CommRoleBonusLayoutGroupNode:__delete()
	self.isInitDropDown  = nil
	self.alignCellList = nil
	self.selectIndex = nil
end

function CommRoleBonusLayoutGroupNode:Awake()
	self:InitAction()
end

function CommRoleBonusLayoutGroupNode:InitAction()
	SetButtonAction(self.BtnDetails, Bind(self, self.OnBtnAlignAction))
end

function CommRoleBonusLayoutGroupNode:SetSelectIndex(index)
	self.selectIndex = index
end

function CommRoleBonusLayoutGroupNode:OnBtnAlignAction()
	local go = self:GetIsDownGo()
	CfUtils.SetActive(go.gameObject, true )
	self:InitAlignDropDown(self.selectIndex)
end

function CommRoleBonusLayoutGroupNode:RefreshShow(data,isDown,excludeDialogs)
	self.showData = data
	self.isDown = isNull(isDown) and true or isDown
	self.excludeDialogs = checkTable(excludeDialogs)
	self:SetAlignNodeShow()
end

function CommRoleBonusLayoutGroupNode:SetAlignNodeShow()
	self.curStar = -1
	local hasCard = cardComp:IsHasCard(self.showData.refId)
	if hasCard then
		local cardDojo = cardComp:GetCardByConfId(self.showData.refId)
		local star = cardDojo.star
		self.curStar = star
		self:RefreshAlignNode(star + 1, self.curStar)
	else
		self:RefreshAlignNode(1, 0)
	end
end

function CommRoleBonusLayoutGroupNode:RefreshAlignNode(index, curStar)
	---@type CommonRoleUpStarNode
	local env = CfUtils.GetLuaScr(self.BtnAlign,"Game.Behaviours.CommonRoleUpStarNode")
	if env then
		env:RefreshCellShow(self.showData, index, curStar, self.excludeDialogs)
	end
end

function CommRoleBonusLayoutGroupNode:InitAlignDropDown(selectIndex)
	if self.isInitDropDown then
		return
	end
	self:InitAlignDropDownAction()
	local AlignDropDown = self:GetIsDownGo()
	local AlignCell = self.AlignCell
	local cellCount = 1
	local showData = self.showData.additions
	local count = table.count(showData)
	local forTimes = math.max(count, cellCount)
	for i = 1, forTimes do
		local data = showData[i]
		local alignCell = self.alignCellList[i]
		if data then
			if alignCell == nil then
				alignCell = AlignDropDown.gameObject:AddChild(AlignCell.gameObject)
				self.alignCellList[i] = alignCell
			end
			
			local cellEnv = CfUtils.GetLuaScr(alignCell, CommRoleBonusLayoutGroupCell)
			if cellEnv then
				local isShowLine = i ~= forTimes
				cellEnv:RefreshUI(data, self.curStar,isShowLine)
				CfUtils.SetActive(alignCell.gameObject, true)
			end
		elseif alignCell then
			CfUtils.SetActive(alignCell.gameObject, false)
		end
	end
	
	self.isInitDropDown = true
end

function CommRoleBonusLayoutGroupNode:InitAlignDropDownAction()
	local go = self:GetIsDownGo()
	local behaviourAction = CfUtils.GetOrAddComponent(go.gameObject, typeof(BehaviourAction))
	if behaviourAction then
		behaviourAction.UpdateAction = Bind(self, self.Update)
		self._behaviourAction = behaviourAction
	end
end

function CommRoleBonusLayoutGroupNode:Update()
	if Utils.TouchCount() > 0 then
		local positionV = Utils.GetInputDownPos()
		local position = Vector2.New(positionV.x, positionV.y)
		if position ~= Vector2.zero then
			local go = self:GetIsDownGo()
			local isInRect = RectTransformUtility.RectangleContainsScreenPoint(go.transform, position,
					self.uiRenderCamera or UIModule.RootCanvas.canvas.worldCamera)
			if not isInRect then
				---不在区域中
				CfUtils.SetActive(self.AlignDropDown.gameObject, false)
				CfUtils.SetActive(self.AlignPullUP.gameObject, false)
			end
		end
	end
end

function CommRoleBonusLayoutGroupNode:GetIsDownGo()
	return self.isDown and self.AlignDropDown or self.AlignPullUP
end

function CommRoleBonusLayoutGroupNode:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return CommRoleBonusLayoutGroupNode